const event = $input.item.json;

const title = event.summary || 'Untitled Event';
const start = event.start?.dateTime || event.start?.date || 'TBD';
const end = event.end?.dateTime || event.end?.date || '';
const location = event.location || '';
const description = (event.description || '').substring(0, 500);
const status = event.status || 'confirmed';
const updated = event.updated || '';
const organizer = event.organizer?.email || '';

// Determine if this is new, updated, or cancelled
let changeType = 'new';
if (status === 'cancelled') changeType = 'cancelled';
else if (updated && new Date(updated) > new Date(Date.now() - 5 * 60 * 1000)) changeType = 'updated';

return [{
  json: {
    title,
    start,
    end,
    location,
    description,
    status,
    changeType,
    organizer,
    eventId: event.id
  }
}];

