const response = $input.item.json;
const eventData = $('Extract Event Details').item.json;
const summary = response.content[0].text;

const changeEmoji = {
  new: '\uD83D\uDCC5',
  updated: '\uD83D\uDD04',
  cancelled: '\u274C'
};

const changeLabel = {
  new: 'New Event',
  updated: 'Event Updated',
  cancelled: 'Event Cancelled'
};

let message = `${changeEmoji[eventData.changeType] || '\uD83D\uDCC5'} *${changeLabel[eventData.changeType] || 'Calendar'}*\n\n`;
message += `${summary}`;

return [{
  json: {
    message,
    to: 'YOUR_PHONE_NUMBER',
    eventData,
    summary
  }
}];
